// Cada estudio puede tener su propio subdominio: el host define a qué estudio pertenece la puerta.
//   obligo-laser.lasersolutions.com.uy      -> sólo usuarios de Laser Solutions
//   obligo-vcestudio.lasersolutions.com.uy  -> sólo usuarios del Estudio Valeria Calvette
// En cualquier otro host (vercel.app, localhost) siguen entrando ambos, como hasta ahora.
function hostStudio(){
  if(typeof window==="undefined")return null;
  const h=(window.location.hostname||"").toLowerCase();
  if(h.includes("obligo-laser")||h.includes("laser-obligo"))return "laser";
  if(h.includes("vcestudio")||h.includes("obligo-vc"))return "vc";
  return null;
}
// Reescribe la paleta viva. Todo lo que lee C cambia de marca y de apariencia
// en el mismo acto; el <html> lleva los mismos datos para que el CSS base
// (fondo, scrollbar, autocompletado del navegador) acompañe.
function aplicarTema(estudio,tema){
  ACTIVE_STUDIO=estudio||ACTIVE_STUDIO;
  ACTIVE_TEMA=tema||ACTIVE_TEMA;
  const oscuro=ACTIVE_TEMA==="oscuro";
  const marca=(MARCAS[ACTIVE_STUDIO]||MARCAS.vc)[oscuro?"oscuro":"claro"];
  Object.assign(C,oscuro?NEUTROS_OSCURO:NEUTROS_CLARO,marca,{gold:marca.accent});
  Object.assign(SH,oscuro?SOMBRAS_OSCURO:SOMBRAS_CLARO);
  try{lbl={...lbl,color:C.gray};inp={...inp,border:`1px solid ${C.border}`,background:C.card,color:C.navy};}catch(e){}
  try{
    const r=document.documentElement;
    r.setAttribute("data-theme",oscuro?"dark":"light");
    r.setAttribute("data-brand",ACTIVE_STUDIO);
    r.style.setProperty("--app-bg",C.bg);
    r.style.setProperty("--app-ink",C.navy);
    r.style.setProperty("--app-border",C.borderStrong);
    r.style.setProperty("--app-card",C.card);
    r.style.setProperty("--app-focus",C.blueTxt);
    // El body se pinta a mano además de por la variable: es lo que se ve al
    // hacer scroll más allá del contenido y en la barra de la PWA.
    if(document.body){document.body.style.background=C.bg;document.body.style.color=C.navy;}
    const meta=document.querySelector('meta[name="theme-color"]');
    if(meta)meta.setAttribute("content",C.dark);
  }catch(e){}
}
function applyStudio(id){aplicarTema(id,ACTIVE_TEMA);}
