const rMap=()=>({irpf_cat1:["IRPF I",C.purple],irpf_cat2:["IRPF II",C.blueTxt],irae:["IRAE",C.navy]});
const vMap=()=>({basica:["IVA 22%",C.blueTxt],reducida:["IVA 10%",C.teal],minimo:["IVA Min",C.warnTxt],sp:["IVA SP",C.teal],monotributo:["MONO",C.ok]});
function taxTags(taxes){
  if(!taxes)return[];
  const t=[];
  if(rMap()[taxes.renta])t.push(rMap()[taxes.renta]);
  if(vMap()[taxes.iva])  t.push(vMap()[taxes.iva]);
  if(taxes.patrimonio) t.push(["IP",C.red]);
  return t;
}
function isConf(c){const t=c.taxes;return t&&(t.renta!=="ninguno"||t.iva!=="no_aplica"||t.patrimonio);}

