const TAX_FILTERS=[
  ["all","Todos los impuestos"],
  ["irae","Renta: IRAE"],["irae_ficto","Renta: IRAE ficto"],["irpf_cat1","Renta: IRPF Cat. I"],["irpf_cat2","Renta: IRPF Cat. II"],
  ["iva_basica","IVA 22%"],["iva_reducida","IVA 10%"],["iva_minimo","IVA Mínimo (Lit. E)"],["iva_sp","IVA Serv. Personales"],["monotributo","Monotributo"],["iva_no","Sin IVA"],
  ["patrimonio","Impuesto al Patrimonio"],
  ["empleados","Con empleados (BPS)"],["efact_pend","e-Factura pendiente"],
  ["sin_config","Sin configurar"],["especial","Etiqueta especial"],
];
// Accesos rápidos: los filtros que un contador usa todos los meses
const TAX_QUICK=()=>[["irae","IRAE",C.navy],["irpf_cat2","IRPF II",C.purple],["iva_basica","IVA 22%",C.blueTxt],["iva_minimo","IVA Mínimo",C.warnTxt],["iva_sp","IVA SP",C.teal],["patrimonio","Patrimonio",C.red],["empleados","Con empleados",C.okTxt],["sin_config","Sin configurar",C.gray]];
function matchTaxFilter(c,f){
  if(!f||f==="all")return true;
  const t=c.taxes||{};
  switch(f){
    case "irae":return t.renta==="irae";
    case "irae_ficto":return t.renta==="irae"&&!!t.iraeEsFicto;
    case "irpf_cat1":return t.renta==="irpf_cat1";
    case "irpf_cat2":return t.renta==="irpf_cat2";
    case "iva_basica":return t.iva==="basica";
    case "iva_reducida":return t.iva==="reducida";
    case "iva_minimo":return t.iva==="minimo";
    case "iva_sp":return t.iva==="sp";
    case "monotributo":return t.iva==="monotributo";
    case "iva_no":return !t.iva||t.iva==="no_aplica";
    case "patrimonio":return !!t.patrimonio;
    case "empleados":return !!c.hasEmployees&&(c.employees||[]).length>0;
    case "efact_pend":return c.efactura==="pendiente";
    case "sin_config":return !isConf(c);
    case "especial":return !!c.specialTag;
    default:return true;
  }
}

// ─── RULES ENGINE ─────────────────────────────────────────────────
function getObs(client,period=""){const _pm=parseInt((period||"").split("/")[0]||"0");
  const t=client.taxes||{};
  const obs=[];
  const M=(o)=>obs.push({freq:"mensual", paid:false,notified:false,...o});
  const A=(o)=>obs.push({freq:"anual",   paid:false,notified:false,...o});
  const E=(o)=>obs.push({freq:"especial",paid:false,notified:false,...o});
  if(t.renta==="irpf_cat1"){M({id:"irpf1",label:"Control retenciones IRPF Cat I",org:"DGI",url:"dgi"});A({id:"dj_irpf1",label:"DDJJ IRPF anual – Form. 1102 (Cat I)",org:"DGI",form:"1102",url:"dgi"});}
  if(t.renta==="irpf_cat2"){M({id:"irpf2",label:"Anticipo IRPF Cat II",org:"DGI",url:"dgi"});M({id:"bps_ind",label:"Aportes BPS titular/independiente",org:"BPS",url:"bps"});A({id:"dj_irpf2",label:"DDJJ IRPF anual – Form. 1102 (Cat II)",org:"DGI",form:"1102",url:"dgi"});}
  if(t.renta==="irae"){A({id:"dj_irae",label:"DDJJ IRAE anual (25% renta neta)",org:"DGI",url:"dgi"});}
  if(t.patrimonio&&t.renta!=="ninguno")A({id:"dj_ip",label:"DDJJ Impuesto al Patrimonio – Declaración anual",org:"DGI",url:"dgi"});
  if(t.iva==="minimo"){M({id:"dj_min",label:"Pago IVA Mínimo – Boleto 2908",org:"DGI",form:"2908",url:"dgi",autoCalc:true});M({id:"bps_lit",label:"Aportes BPS titular (Literal E)",org:"BPS",url:"bps"});}
  if(t.iva==="sp")M({id:"dj_1302",label:"DJ IVA Serv. Personales – Form. 1302",org:"DGI",form:"1302",url:"dgi"});
  if(t.iva==="monotributo")M({id:"mt",label:"Cuota Monotributo unificada (BPS+DGI)",org:"BPS/DGI",url:"bps",autoCalc:true});
  // 2908 consolidado: IRAE + IP + ICOSA (salvo monotributo y literal E)
  if(isConf(client)&&t.iva!=="monotributo"&&t.iva!=="minimo"&&t.renta!=="ninguno")
    M({id:"form2908",label:"Anticipo impuestos – Boleto 2908",org:"DGI",form:"2908",url:"dgi"});
  // 2178 anual: aparece 0-60 días después del cierre de balance
  if((t.iva==="basica"||t.iva==="reducida")&&client.cierreBalance){
    const _cbParts=client.cierreBalance.split("/");const _cbYr=new Date().getFullYear();
    let _cbDate=new Date(_cbYr,+_cbParts[1]-1,+_cbParts[0]);
    if(_cbDate>new Date(TODAY))_cbDate.setFullYear(_cbYr-1);
    const _cbDeadline=new Date(_cbDate);_cbDeadline.setDate(_cbDeadline.getDate()+60);
    const _cbNow=new Date(TODAY);
    if(_cbNow>=_cbDate&&_cbNow<=_cbDeadline)A({id:"dj_iva_anual",label:"DJ IVA anual – Form. 2178",org:"DGI",form:"2178",url:"dgi"});
  }
  if(client.entityType==="sas")M({id:"fonasa_sas",label:"FONASA directores SAS (mín. 15 BFC)",org:"BPS",url:"bps"});
  if(["sa","sas"].includes(client.entityType))A({id:"bcu",label:"Beneficiarios finales BCU (Ley 19.484)",org:"BCU"});
  if(client.nature==="construccion"){M({id:"focer",label:"FOCER – Cesantía Construcción",org:"BPS",url:"bps"});M({id:"fsc",label:"Fondo Social Construcción",org:"BPS",url:"bps"});M({id:"fosvoc",label:"FOSVOC – Vivienda Obrera",org:"BPS",url:"bps"});}
  if(client.specialTaxes?.includes("gasoil"))A({id:"gasoil",label:"DJ Gasoil – Form. 2181",org:"DGI",form:"2181",url:"dgi"});
  if(client.hasEmployees){
    M({id:"bps_nom",label:"Declaración nominada nómina (BPS)",org:"BPS",url:"bps",needsNominas:true});
    M({id:"nominas",label:"Nóminas",org:"BPS/DGI"});
    M({id:"irpf_dep",label:"Retención IRPF dependientes (código 104)",org:"BPS/DGI",url:"bps"});
    A({id:"bse_seg",label:"Seguro accidentes laborales (BSE)",org:"BSE",url:"bse"});
    if(_pm===6)E({id:"aguin_jun",label:"Aguinaldo – 1ª cuota (junio)",org:"DGI/BPS"});
    if(_pm===12)E({id:"aguin_dic",label:"Aguinaldo – 2ª cuota (diciembre)",org:"DGI/BPS"});
    if(_pm===12)E({id:"aj_dic",label:"Ajuste anual IRPF dependientes (dic.)",org:"DGI/BPS"});
  }
  if(t.iva!=="monotributo"&&isConf(client))M({id:"efact",label:"Control e-Factura CFE",org:"DGI",url:"dgi"});
  return obs;
}

// ─── CALC 2908 ─────────────────────────────────────────────────────
// Renglones del boleto 2908 de un período. Los importes salen del cálculo del mes
// (coeficiente vs. mínimo en IRAE, IVA según la facturación cargada) y cada uno se
// puede pisar a mano desde Tributario: queda guardado en client.anticipos[período].
function calc2908(client,cfg={},period=""){
  const t=client.taxes||{};
  const per=period||PINIT;
  const ov=(client.anticipos||{})[per]||{};
  const a=calcAnticipos(client,per,cfg);
  const items=[];
  const add=(key,label,auto,hint)=>{
    const manual=ov[key]!=null&&ov[key]!=="";
    items.push({key,label,monto:Math.round(manual?+ov[key]||0:auto||0),auto:Math.round(auto||0),manual,hint:hint||""});
  };
  if(t.renta==="irae"){
    const usaMin=t.iraeEsMinimo||!(a.iraeCoef>a.iraeMin);
    add("irae","Anticipo IRAE",t.iraeEsMinimo?a.iraeMin:a.irae,
      t.iraeMontoMensual!=null&&t.iraeMontoMensual!==""&&!t.iraeEsMinimo?"Monto fijo del cliente"
      :usaMin?`Mínimo del año ($ ${fU(a.iraeMin,0)})`
      :`Coeficiente ${t.iraeCoeficiente} sobre la facturación`);
  }
  if(t.renta==="irpf_cat2")add("irpf","Anticipo IRPF Categoría II",a.irpf,
    a.irpf2&&a.ventas?`70% de $ ${fU(a.ventas,0)} = $ ${fU(a.irpf2.base,0)} por la escala`:"Falta cargar la facturación del mes");
  if(t.patrimonio&&t.renta!=="ninguno")add("ip","Anticipo Impuesto al Patrimonio",a.ip,t.ipMontoAnual?`Anual: $ ${fU(+t.ipMontoAnual,0)}`:"");
  if(client.entityType==="sa")add("icosa","ICOSA mensual",client.icosaMonto||0);
  if(t.iva==="minimo")add("ivaMin","IVA Mínimo — Literal E",cfg.ivaMinimo||0,"Valor fijo del año");
  else if(t.iva==="basica"||t.iva==="reducida")add("iva",`IVA del mes (tasa ${t.iva==="basica"?"básica 22%":"reducida 10%"})`,a.pagoIVA,
    a.excedente>0?`Mes sin pago · quedan $ ${fU(a.excedente,2)} de excedente para el mes que viene`
    :a.cargado?"Según la facturación cargada":"Falta cargar la facturación del mes");
  const total=items.reduce((s,x)=>s+x.monto,0);
  return {items,total};
}

// Aportes de BPS del mes, sumando la liquidación de cada empleado.
function aportesBPS(client,period,config){
  if(!client.hasEmployees||!(client.employees||[]).length)return 0;
  const inc=(client.sueldos||{})[period]||{};
  const opts={period,bpc:config?.bpc||6864,antigTope:client.antigTope!=null?client.antigTope:null};
  return Math.round((client.employees||[]).reduce((a,e)=>a+calcRecibo(e,inc[e.id]||{},opts).aportes,0));
}

// Los servicios personales NO profesionales pagan dos facturas al BPS: la de
// FONASA y la de Industria y Comercio. (Los profesionales aportan a su caja,
// no al BPS.) El resto paga una sola. Se puede forzar con client.bpsDoble.
function bpsDoble(c){
  if(c.bpsDoble!=null)return !!c.bpsDoble;
  return (c.taxes||{}).iva==="sp"||c.nature==="servicios_personales";
}

// Los boletos que este cliente realmente paga cada mes. De acá salen tanto la
// línea del Panel como la pantalla de Pagos / Trámites, para que no se puedan
// contradecir.
function boletosDe(client,period,config){
  const obs=getObs(client,period).filter(o=>o.freq==="mensual");
  const out=[];
  if(obs.some(o=>(o.org||"").includes("DGI")))
    out.push({id:"dgi",org:"DGI",label:"DGI — Boleto 2908",corto:"DGI",logo:LOGO_DGI,color:C.red,
      vto:vtoDGI(period,config?.diaDGI,client.grupoDGI),auto:calc2908(client,config,period).total});
  if(obs.some(o=>(o.org||"").includes("BPS"))){
    const vb=vtoBPS(period,config?.diaBPS);
    if(bpsDoble(client)){
      out.push({id:"bps_fonasa",org:"BPS",label:"BPS — FONASA",corto:"FONASA",logo:LOGO_BPS,color:C.blueTxt,vto:vb,auto:0});
      out.push({id:"bps_ic",org:"BPS",label:"BPS — Industria y Comercio",corto:"BPS Ind. y Com.",logo:LOGO_BPS,color:C.blueTxt,
        vto:vb,auto:aportesBPS(client,period,config)});
    }else{
      out.push({id:"bps",org:"BPS",label:"BPS",corto:"BPS",logo:LOGO_BPS,color:C.blueTxt,vto:vb,
        auto:aportesBPS(client,period,config)});
    }
  }
  return out;
}

// Lo que hay que pagar este mes en cada organismo: es la línea que se ve en el Panel.
function resumenMes(client,period,config){
  return boletosDe(client,period,config).map(b=>{
    const g=client.boletos?.[period]?.[b.id]||{};
    return{...b,org:b.id,label:b.corto,
      vto:g.vto?isoAFecha(g.vto):b.vto,
      monto:g.monto!=null&&g.monto!==""?+g.monto:b.auto};
  });
}

