// Calcula aportes y líquido según BPS Uruguay
function calcNomina(emp){
  const bruto=emp.tipo==="mensual"?(emp.sueldo||0):(emp.jornal||0)*22; // jornal * 22 días hábiles promedio
  const jubilacion=bruto*0.15;
  const fonasa=bruto*(0.03+emp.menores*0.015);
  const frl=bruto*0.00125;
  const totalAportes=jubilacion+fonasa+frl;
  const liquido=Math.max(0,bruto-totalAportes);
  return {bruto,jubilacion,fonasa,frl,totalAportes,liquido};
}
