function Ico({n,size=18,style={},sw=1.6}){
  return<svg viewBox="0 0 24 24" width={size} height={size} fill="none" stroke="currentColor" strokeWidth={sw}
    strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" style={{flexShrink:0,display:"block",...style}}>
    {ICONOS[n]||ICONOS.punto}
  </svg>;
}

function SpecialTag({tag,size=10}){
  if(!tag)return null;const col=SPECIAL_TAG_COLOR()[tag]||C.gray;
  return<span style={{background:col+"14",color:col,border:`1px solid ${col}45`,padding:"1px 8px",borderRadius:99,fontSize:size,fontWeight:700,fontFamily:F,letterSpacing:.3,whiteSpace:"nowrap"}}>{tag}</span>;
}


// ─── UI PRIMITIVES ────────────────────────────────────────────────
function openUrl(u){window.open(u,"_blank","noopener");}
function initials(n){return n.split(" ").slice(0,2).map(w=>w[0]||"").join("").toUpperCase();}

// Logo with white bg container for dark-background logos
function Logo({src,size=18,style={}}){
  return<div style={{background:C.card,borderRadius:5,padding:2,display:"inline-flex",alignItems:"center",justifyContent:"center",...style}}>
    <img src={src} alt="" style={{height:size,objectFit:"contain"}}/>
  </div>;
}
// Logo without container (for places with light bg already)
function LogoRaw({src,size=18,style={}}){
  return<img src={src} alt="" style={{height:size,objectFit:"contain",...style}}/>;
}

function Avatar({name,taxes,size=36}){
  const tags=taxTags(taxes);
  const col=tags[0]?.[1]||C.gray;
  return<div style={{width:size,height:size,borderRadius:"50%",background:col+"25",border:`1.5px solid ${col}55`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:size*.33,fontWeight:700,color:col,flexShrink:0,fontFamily:F}}>{initials(name)}</div>;
}
function TBadge({taxes}){
  const tags=taxTags(taxes);
  if(!tags.length)return<span style={{background:C.red+"15",color:C.red,border:`1px solid ${C.red}40`,padding:"2px 6px",borderRadius:3,fontSize:10,fontWeight:700,fontFamily:F}}>S/C</span>;
  return<div style={{display:"flex",gap:3,flexWrap:"wrap"}}>{tags.map(([l,col])=><span key={l} style={{background:col+"15",color:col,border:`1px solid ${col}40`,padding:"2px 6px",borderRadius:3,fontSize:10,fontWeight:700,fontFamily:F,whiteSpace:"nowrap"}}>{l}</span>)}</div>;
}
function OBadge({org}){
  const key=Object.keys(ORG_COLOR()).find(k=>org?.includes(k))||"Otro";
  const col=ORG_COLOR()[key];
  return<span style={{background:col+"15",color:col,border:`1px solid ${col}30`,padding:"1px 6px",borderRadius:3,fontSize:10,fontWeight:700,fontFamily:F}}>{org}</span>;
}
