                    <button onClick={()=>{if(window.confirm("¿Eliminar?"))upd("certsDGI",(client.certsDGI||[]).filter((_,ii)=>ii!==ci));}} style={{fontSize:10,padding:"3px 8px",borderRadius:4,border:`1px solid ${C.red}30`,background:C.red+"10",color:C.red,cursor:"pointer",fontFamily:F}}>✕</button>
