// ─── EXCEL EXPORT ────────────────────────────────────────────────
function exportExcel(clients,period){
  import("xlsx").then(XLSX=>{
    const wb=XLSX.utils.book_new();
    const HDR_FILL={fgColor:{rgb:"021942"}};
    const HDR_FONT={bold:true,color:{rgb:"FFFFFF"},sz:11};
    const BORDER={top:{style:"thin",color:{rgb:"C7D2E0"}},bottom:{style:"thin",color:{rgb:"C7D2E0"}},left:{style:"thin",color:{rgb:"C7D2E0"}},right:{style:"thin",color:{rgb:"C7D2E0"}}};
    const mkStyle=(fill,font)=>({fill:{patternType:"solid",...fill},font:{...font,name:"Calibri"},border:BORDER,alignment:{vertical:"center",horizontal:"left"}});
    const HDR=mkStyle(HDR_FILL,HDR_FONT);
    const ROW_E=mkStyle({fgColor:{rgb:"EBF5FF"}},{sz:10,color:{rgb:"021942"}});
    const ROW_O=mkStyle({fgColor:{rgb:"FFFFFF"}},{sz:10,color:{rgb:"021942"}});
    const TOT=mkStyle({fgColor:{rgb:"D4E9FF"}},{bold:true,sz:10,color:{rgb:"021942"}});

    // Resumen clientes
    const resHdrs=["Razón Social","RUT","Nº BPS","Giro","Tipo","Renta","IVA","Has Empl.","Cert DGI Vto.","Cierre Bal.","Estado"];
    const resRows=clients.map(c=>[
      c.name,c.rut||"",c.numEmpresa||"",c.giro||"",
      ENTITY[c.entityType]||c.entityType,
      RENTA_OPT.find(([k])=>k===c.taxes?.renta)?.[1]||"–",
      IVA_OPT.find(([k])=>k===c.taxes?.iva)?.[1]||"–",
      c.hasEmployees?"Sí":"No",(c.certsDGI||[]).filter(x=>!x.usado).map(x=>x.vencimiento).join("; ")||"",c.cierreBalance||"",
      c.status==="activo"?"Activo":"Inactivo"
    ]);
    const wsRes=XLSX.utils.aoa_to_sheet([resHdrs,...resRows]);
    resHdrs.forEach((_,i)=>{const cell=wsRes[XLSX.utils.encode_cell({r:0,c:i})];if(cell)cell.s=HDR;});
    resRows.forEach((_,r)=>resHdrs.forEach((_,c)=>{const cell=wsRes[XLSX.utils.encode_cell({r:r+1,c})];if(cell)cell.s=r%2===0?ROW_E:ROW_O;}));
    wsRes["!cols"]=resHdrs.map((_,i)=>({wch:i===0?28:i===3?22:14}));
    XLSX.utils.book_append_sheet(wb,wsRes,"Clientes");

    // Tareas del período
    const tarHdrs=["Cliente","Tarea","Vencimiento","Categoría","Frecuencia","Estado","Pagado","Notif."];
    const tarRows=clients.flatMap(c=>c.tasks.map(t=>[c.name,t.label,t.due,t.cat,t.freq,t.done?"Completada":"Pendiente",t.paid?"Sí":"No",t.notified?"Sí":"No"]));
    const wsTar=XLSX.utils.aoa_to_sheet([tarHdrs,...tarRows]);
    tarHdrs.forEach((_,i)=>{const cell=wsTar[XLSX.utils.encode_cell({r:0,c:i})];if(cell)cell.s=HDR;});
    tarRows.forEach((_,r)=>tarHdrs.forEach((_,c)=>{const cell=wsTar[XLSX.utils.encode_cell({r:r+1,c})];if(cell)cell.s=r%2===0?ROW_E:ROW_O;}));
    wsTar["!cols"]=[{wch:24},{wch:36},{wch:14},{wch:12},{wch:12},{wch:13},{wch:9},{wch:9}];
    XLSX.utils.book_append_sheet(wb,wsTar,"Tareas");

    // Empleados
    const empHdrs=["Empresa","Nombre Empleado","CI","Cargo","Tipo","Sueldo/Jornal","Menores","Bruto","Aportes","Líquido est."];
    const empRows=clients.filter(c=>c.hasEmployees).flatMap(c=>c.employees.map(e=>{
      const n=calcNomina(e);
      return[c.name,e.name,e.ci||"",e.cargo||"",e.tipo||"mensual",e.tipo==="jornalero"?e.jornal:e.sueldo,e.menores||0,Math.round(n.bruto),Math.round(n.totalAportes),Math.round(n.liquido)];
    }));
    const wsEmp=XLSX.utils.aoa_to_sheet([empHdrs,...empRows]);
    empHdrs.forEach((_,i)=>{const cell=wsEmp[XLSX.utils.encode_cell({r:0,c:i})];if(cell)cell.s=HDR;});
    empRows.forEach((_,r)=>empHdrs.forEach((_,c)=>{const cell=wsEmp[XLSX.utils.encode_cell({r:r+1,c})];if(cell)cell.s=r%2===0?ROW_E:ROW_O;}));
    // Total row
    const totRow=["","","","","","TOTAL","",0,0,0];
    empRows.forEach(r=>{totRow[7]+=r[7]||0;totRow[8]+=r[8]||0;totRow[9]+=r[9]||0;});
    const totAoa=[totRow];const wsTotStart=empRows.length+1;
    XLSX.utils.sheet_add_aoa(wsEmp,totAoa,{origin:wsTotStart});
    empHdrs.forEach((_,i)=>{const cell=wsEmp[XLSX.utils.encode_cell({r:wsTotStart,c:i})];if(cell)cell.s=TOT;});
    wsEmp["!cols"]=[{wch:24},{wch:22},{wch:14},{wch:16},{wch:11},{wch:14},{wch:9},{wch:12},{wch:12},{wch:14}];
    XLSX.utils.book_append_sheet(wb,wsEmp,"Empleados");

    XLSX.writeFile(wb,`Obligo_${period.replace("/","-")}.xlsx`);
  });
}

// ─── MAIN APP ─────────────────────────────────────────────────────
// ─── CAMPANA DE AVISOS + NOTIFICACIONES DE ESCRITORIO ─────────────
function NotifBell({clients}){
  const [open,setOpen]=useState(false);
  const [perm,setPerm]=useState(typeof Notification!=="undefined"?Notification.permission:"unsupported");
  const items=useMemo(()=>{
    const out=[];
    clients.forEach(c=>{
      (c.certsDGI||[]).filter(cert=>!cert.usado&&cert.vencimiento).forEach(cert=>{const dd=daysUntil(cert.vencimiento);if(dd!==null&&dd>=0&&dd<60)out.push({sev:dd<=7?"red":"warn",cli:c.name,txt:`Certificado DGI vence en ${dd} día${dd!==1?"s":""}`,due:cert.vencimiento});});
      (c.tasks||[]).forEach(t=>{
        if(!t.done&&t.due<TODAY)out.push({sev:"red",cli:c.name,txt:`${t.label} — vencida el ${t.due.split("-").reverse().join("/")}`,due:t.due});
        else if(!t.done&&t.due>=TODAY&&t.due<=dateAdd(TODAY,7))out.push({sev:"warn",cli:c.name,txt:`${t.label} — vence el ${t.due.split("-").reverse().join("/")}`,due:t.due});
      });
    });
    return out.sort((a,b)=>(a.sev==="red"?0:1)-(b.sev==="red"?0:1)||a.due.localeCompare(b.due));
  },[clients]);
  const red=items.filter(i=>i.sev==="red").length;
  // Notificación nativa de Windows: una por día y por estudio
  useEffect(()=>{
    if(perm!=="granted"||items.length===0)return;
    const key=`obligo_notif_${ACTIVE_STUDIO}_${TODAY}`;
    try{
      if(localStorage.getItem(key))return;
      localStorage.setItem(key,"1");
      new Notification(ACTIVE_STUDIO==="laser"?"Laser Solutions — Avisos del día":"Obligo — Avisos del día",{
        body:`${items.length} aviso${items.length!==1?"s":""}${red?` · ${red} vencido${red!==1?"s":""}`:""}. Abrí la app para ver el detalle.`,
        icon:ACTIVE_STUDIO==="laser"?LOGO_LASER_ISO:undefined,tag:"obligo-daily",
      });
    }catch(e){}
  },[perm,items.length,red]);
  const askPerm=()=>{if(typeof Notification!=="undefined")Notification.requestPermission().then(p=>setPerm(p));};
  return<div style={{position:"relative",flexShrink:0}}>
    <button onClick={()=>setOpen(p=>!p)} title="Avisos y vencimientos" style={{position:"relative",background:open?C.navy:"transparent",border:`1px solid ${open?C.navy:C.border}`,borderRadius:8,padding:"4px 9px",cursor:"pointer",fontSize:15,lineHeight:1.2,color:open?"#fff":C.navy}}>
      <Ico n="alertas" size={16}/>{items.length>0&&<span style={{position:"absolute",top:-6,right:-6,minWidth:16,height:16,borderRadius:99,background:red>0?C.red:C.warn,color:"#fff",fontSize:9.5,fontWeight:800,display:"flex",alignItems:"center",justifyContent:"center",padding:"0 4px",fontFamily:F,border:"2px solid #fff",boxSizing:"content-box"}}>{items.length>99?"99+":items.length}</span>}
    </button>
    {open&&<>
      <div onClick={()=>setOpen(false)} style={{position:"fixed",inset:0,zIndex:140}}/>
      <div style={{position:"absolute",right:0,top:38,width:330,maxWidth:"86vw",background:C.card,border:`1px solid ${C.border}`,borderRadius:12,boxShadow:SH.lg,zIndex:150,overflow:"hidden"}}>
        <div style={{background:C.raised,padding:"10px 14px",display:"flex",alignItems:"center",justifyContent:"space-between"}}>
          <div style={{color:"#fff",fontWeight:700,fontSize:13,fontFamily:F}}>Avisos y vencimientos</div>
          <div style={{fontSize:10.5,color:"#8ECBDE",fontFamily:F,fontWeight:600}}>{items.length===0?"Al día ✓":`${items.length} aviso${items.length!==1?"s":""}`}</div>
        </div>
        <div style={{maxHeight:330,overflowY:"auto"}}>
          {items.length===0&&<div style={{padding:"26px 14px",textAlign:"center",color:C.gray,fontSize:12.5,fontFamily:F,display:"flex",flexDirection:"column",alignItems:"center",gap:7}}><span style={{color:C.okTxt,display:"flex"}}><Ico n="listo" size={26}/></span>Sin vencimientos próximos.<br/>Todo en orden.</div>}
          {items.map((it,i)=><div key={i} style={{padding:"9px 14px",borderBottom:`1px solid ${C.border}60`,display:"flex",gap:9,alignItems:"flex-start"}}>
            <div style={{width:8,height:8,borderRadius:99,marginTop:4,flexShrink:0,background:it.sev==="red"?C.red:C.warnTxt}}/>
            <div style={{minWidth:0}}>
              <div style={{fontSize:12,fontWeight:700,color:C.navy,fontFamily:F}}>{it.cli}</div>
              <div style={{fontSize:11,color:C.gray,fontFamily:F,lineHeight:1.4}}>{it.txt}</div>
            </div>
          </div>)}
        </div>
        {perm!=="unsupported"&&<div style={{padding:"9px 14px",borderTop:`1px solid ${C.border}`,background:C.bg}}>
          {perm==="granted"
            ?<div style={{fontSize:10.5,color:C.okTxt,fontFamily:F,fontWeight:600}}>✓ Avisos de escritorio activados — te llega una notificación de Windows por día con los vencimientos.</div>
            :perm==="denied"
              ?<div style={{fontSize:10.5,color:C.gray,fontFamily:F}}>Las notificaciones están bloqueadas en el navegador. Activalas desde el candado de la barra de direcciones.</div>
              :<button onClick={askPerm} style={{width:"100%",background:C.blue,color:"#fff",border:"none",borderRadius:7,padding:"7px",fontSize:11.5,fontWeight:700,cursor:"pointer",fontFamily:F,display:"flex",alignItems:"center",gap:6}}><Ico n="pantalla" size={14}/>Activar avisos de escritorio (Windows)</button>}
        </div>}
      </div>
    </>}
  </div>;
}

export default function Obligo(){
  const w=useWW();
  const isMobile=w<700;
  const [sidebarOpen,setSidebarOpen]=useState(false);
  const [authUser,setAuthUser]=useState(null);
  const [studio,setStudio]=useState("vc");
  // C y SH se mutan fuera de React; este contador es lo que fuerza el redibujo
  // cuando cambia la apariencia. Cada estudio guarda la suya.
  const [tema,setTemaEstado]=useState(()=>temaGuardado(hostStudio()||"vc"));
  const [,repintar]=useState(0);
  const setTema=(t)=>{guardarTema(studio,t);setTemaEstado(t);aplicarTema(studio,t);repintar(n=>n+1);};
  const [view,setView]=useState("dashboard");
  const [clientId,setClientId]=useState(null);
  const [clients,setClients]=useState(()=>{
    const g=cargarLista('gc_clients',null);if(g)return g;
    return CLIENTS_INIT;
  });
  useEffect(()=>{if(!authUser)return;try{localStorage.setItem(studio==="laser"?'ls_clients':'gc_clients',JSON.stringify(clients));}catch(e){};},[clients,studio,authUser]);
  const [globalPeriod,setGlobalPeriod]=useState(PINIT);
  const [closedPeriods,setClosedPeriods]=useState([]);
  const [proveedores,setProveedores]=useState([]);
  // Valores fiscales vigentes 2026, los mismos que usa el otro estudio
  const CONFIG_DEFAULT={studioName:"Estudio Valeria Calvette",studioCode:"VCEstudio",studioRut:"",studioEmail:"",studioPhone:"",adminPass:"admin123",secretariaPass:"secr123",diaDGI:22,diaBPS:DIA_BPS_WEB,bpc:6864,ui:6.5720,iraeMinimoMensual:6840,ivaMinimo:5910,monotributoA:2800,monotributoB:5500,icosaAnual:0,icosaMensual:0,salarioMinimo:24572,limiteMonotributoUI:305000,limiteLiteralEUI:4000000,limite4MUI:4000000,cotizaciones:[]};
  const [config,setConfig]=useState(()=>{
    try{const s=localStorage.getItem('gc_config');if(s)return{...CONFIG_DEFAULT,...JSON.parse(s)};}catch(e){}
    return CONFIG_DEFAULT;
  });
  useEffect(()=>{if(!authUser)return;try{localStorage.setItem(studio==="laser"?'ls_config':'gc_config',JSON.stringify(config));}catch(e){}},[config,studio,authUser]);

  // Cada estudio carga y guarda sus propios datos; los de Valeria Calvette (gc_*) no se tocan desde Laser (ls_*)
  const loadList=cargarLista;
  const loadObj=(key,fallback)=>{try{const s=localStorage.getItem(key);if(s)return{...fallback,...JSON.parse(s)};}catch(e){}return fallback;};
  const handleLogin=(u,st="vc")=>{
    const t=temaGuardado(st);
    aplicarTema(st,t);
    setTemaEstado(t);
    setStudio(st);
    if(st==="laser"){
      let lsC=loadList('ls_clients',CLIENTS_LASER);
      let lsCfg=loadObj('ls_config',LASER_CONFIG_DEFAULT);
      // Migración de datos precargados: al subir la versión del seed se actualizan los 7 clientes base
      // (datos DGI/MTSS nuevos) preservando lo trabajado: sueldos, trámites, nóminas, tareas y credenciales
      let seedOk=false;try{seedOk=localStorage.getItem('ls_seed')===LASER_SEED_V;}catch(e){}
      if(!seedOk){
        const byId={};lsC.forEach(c=>{byId[c.id]=c;});
        lsC=CLIENTS_LASER.map(seed=>{const old=byId[seed.id];if(!old)return seed;
          return{...seed,sueldos:old.sueldos||{},tramites:old.tramites||[],nominas:old.nominas||{},billing:old.billing||{},facturas:old.facturas||{},boletos:old.boletos||{},anticipos:old.anticipos||{},obPagos:old.obPagos||{},aportaciones:old.aportaciones||[],docsLeidos:old.docsLeidos||[],giroDGI:old.giroDGI||seed.giroDGI,giroBPS:old.giroBPS||seed.giroBPS,incidencias:old.incidencias||[],certsDGI:old.certsDGI||[],credentials:old.credentials||seed.credentials,studyFee:old.studyFee,studyFeePaid:old.studyFeePaid,notes:seed.notes};
        }).concat(lsC.filter(c=>!CLIENTS_LASER.some(s=>s.id===c.id)));
        lsCfg={...lsCfg,bpc:LASER_CONFIG_DEFAULT.bpc,ui:LASER_CONFIG_DEFAULT.ui,salarioMinimo:LASER_CONFIG_DEFAULT.salarioMinimo,ivaMinimo:LASER_CONFIG_DEFAULT.ivaMinimo,iraeMinimoMensual:LASER_CONFIG_DEFAULT.iraeMinimoMensual};
        try{localStorage.setItem('ls_seed',LASER_SEED_V);localStorage.setItem('ls_clients',JSON.stringify(lsC));localStorage.setItem('ls_config',JSON.stringify(lsCfg));}catch(e){}
      }
      setClients(lsC);setConfig(migrarVtos(lsCfg,'ls_vtos'));
    }
    else{
      let gcCfg=loadObj('gc_config',CONFIG_DEFAULT);
      // Los valores fiscales guardados eran los de 2025: se actualizan una sola vez a los de 2026.
      // No se toca nada más de la configuración del estudio.
      let valOk=false;try{valOk=localStorage.getItem('gc_valores')===VC_VALORES_V;}catch(e){}
      if(!valOk){
        gcCfg={...gcCfg,bpc:CONFIG_DEFAULT.bpc,ui:CONFIG_DEFAULT.ui,salarioMinimo:CONFIG_DEFAULT.salarioMinimo,ivaMinimo:CONFIG_DEFAULT.ivaMinimo,iraeMinimoMensual:CONFIG_DEFAULT.iraeMinimoMensual};
        try{localStorage.setItem('gc_valores',VC_VALORES_V);localStorage.setItem('gc_config',JSON.stringify(gcCfg));}catch(e){}
      }
      setClients(loadList('gc_clients',CLIENTS_INIT));setConfig(migrarVtos(gcCfg,'gc_vtos'));
    }
    setView("dashboard");setClientId(null);
    setAuthUser(u);
  };
  const handleLogout=()=>{
    aplicarTema("vc",temaGuardado("vc"));setTemaEstado(temaGuardado("vc"));
    setStudio("vc");setAuthUser(null);setView("dashboard");setClientId(null);
    setClients(loadList('gc_clients',CLIENTS_INIT));setConfig(loadObj('gc_config',CONFIG_DEFAULT));
  };

  // El título y el ícono de la pestaña acompañan al estudio (cada subdominio tiene su identidad).
  // En la puerta general sólo se personaliza una vez que se sabe con qué estudio entró.
  useEffect(()=>{
    const hs=hostStudio();
    const st=hs||(authUser?studio:null);
    if(!st)return;
    document.title=st==="laser"?"Laser Solutions · Gestión contable":"Estudio Valeria Calvette · Obligo";
    try{
      let l=document.querySelector("link[rel~='icon']");
      if(!l){l=document.createElement("link");l.rel="icon";document.head.appendChild(l);}
      l.type="image/svg+xml";
      l.href=st==="laser"?LOGO_LASER_ISO:FAVICON_VC;
    }catch(e){}
  },[studio,authUser]);

  const client=useMemo(()=>clients.find(c=>c.id===clientId),[clients,clientId]);
  const openClient=(id)=>{setClientId(id);setView("client");};
  const goBack=()=>{setView("clients");setClientId(null);};
  // Usa la misma fábrica mk() que los clientes precargados: así un cliente nuevo
  // tiene exactamente la misma estructura y ninguna pantalla se rompe por un campo faltante
  const addClient=(form)=>setClients(prev=>[...prev,mk(
    Date.now(),form.name.trim(),form.entityType,form.nature,form.taxes,
    {hasEmployees:form.hasEmployees,employees:(form.employees||[]).map(e=>mkEmpL(e)),efactura:"pendiente",sueldos:{}}
  )]);

  const periodNavFn=(fn)=>{
    const newP=typeof fn==="function"?fn(globalPeriod):fn;
    if(closedPeriods.includes(newP)){if(!window.confirm(`El mes ${newP} está cerrado. ¿Deseas continuar de todas formas?`))return;}
    setGlobalPeriod(newP);
  };
  if(!authUser)return<LoginScreen onLogin={handleLogin}/>;

  return<RCtx.Provider value={{m:isMobile,open:sidebarOpen,setOpen:setSidebarOpen}}>
  <div style={{display:"flex",fontFamily:F,height:"100vh",overflow:"hidden",background:C.bg}}>
    <Sidebar view={view} setView={(v)=>{setView(v);if(v!=="client")setClientId(null);setSidebarOpen(false);}} user={authUser} onLogout={handleLogout}/>
    <div style={{flex:1,display:"flex",flexDirection:"column",overflow:"hidden",minWidth:0}}>
      <div style={{background:C.card,borderBottom:`1px solid ${C.border}`,padding:"8px 14px",display:"flex",alignItems:"center",gap:8,flexShrink:0}}>
        {isMobile&&<button onClick={()=>setSidebarOpen(p=>!p)} style={{background:"transparent",border:`1px solid ${C.border}`,borderRadius:6,padding:"5px 9px",cursor:"pointer",fontSize:17,lineHeight:1,color:C.navy,flexShrink:0,display:"flex",alignItems:"center",justifyContent:"center"}}><Ico n="menu" size={17}/></button>}
        <div style={{flex:1,fontSize:12,color:C.gray,fontFamily:F,minWidth:0,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>
          {view==="client"&&client?<span><span style={{color:C.blueTxt,cursor:"pointer"}} onClick={()=>setView("clients")}>Clientes</span> / {client.name}</span>
            :<span style={{color:C.navy,fontWeight:600}}>{view==="dashboard"?"Panel Principal":view==="clients"?"Clientes":view==="config"?"Configuración":view==="calendario"?"Calendario":view.charAt(0).toUpperCase()+view.slice(1)}</span>}
        </div>
        {!isMobile&&<PeriodNav period={globalPeriod} setPeriod={periodNavFn}/>}
        {!isMobile&&(closedPeriods.includes(globalPeriod)
          ?<span style={{fontSize:11,background:"#FEE2E2",color:C.red,border:`1px solid ${C.red}40`,borderRadius:4,padding:"3px 8px",fontFamily:F,fontWeight:600}}>Cerrado</span>
          :<button onClick={()=>{if(window.confirm(`¿Marcar ${globalPeriod} como mes finalizado?`))setClosedPeriods(p=>[...p,globalPeriod]);}} style={{fontSize:11,background:C.okBg,color:C.okTxt,border:`1px solid ${C.ok}40`,borderRadius:4,padding:"3px 8px",cursor:"pointer",fontFamily:F,fontWeight:600}}>✓ Finalizar mes</button>
        )}
        {!isMobile&&<button onClick={()=>exportExcel(clients,globalPeriod)} style={{fontSize:11,background:C.tint,color:C.blueTxt,border:`1px solid ${C.blue}40`,borderRadius:4,padding:"4px 10px",cursor:"pointer",fontFamily:F,fontWeight:600,display:"flex",alignItems:"center",gap:4}}>↓ Excel</button>}
        <NotifBell clients={clients}/>
        <div style={{width:28,height:28,borderRadius:"50%",background:C.raised,display:"flex",alignItems:"center",justifyContent:"center",color:C.white,fontSize:10,fontWeight:700,fontFamily:F,flexShrink:0}}>{authUser.name.slice(0,2).toUpperCase()}</div>
      </div>
      {isMobile&&<div style={{background:C.card,borderBottom:`1px solid ${C.border}`,padding:"6px 14px",display:"flex",alignItems:"center",gap:8,flexShrink:0}}>
        <PeriodNav period={globalPeriod} setPeriod={periodNavFn}/>
        {closedPeriods.includes(globalPeriod)
          ?<span style={{fontSize:10,background:"#FEE2E2",color:C.red,border:`1px solid ${C.red}40`,borderRadius:4,padding:"2px 6px",fontFamily:F,fontWeight:600}}>Cerrado</span>
          :<button onClick={()=>{if(window.confirm(`¿Marcar ${globalPeriod} como mes finalizado?`))setClosedPeriods(p=>[...p,globalPeriod]);}} style={{fontSize:10,background:C.okBg,color:C.okTxt,border:`1px solid ${C.ok}40`,borderRadius:4,padding:"2px 6px",cursor:"pointer",fontFamily:F,fontWeight:600}}>✓ Cerrar</button>
        }
        <button onClick={()=>exportExcel(clients,globalPeriod)} style={{fontSize:10,background:C.tint,color:C.blueTxt,border:`1px solid ${C.blue}40`,borderRadius:4,padding:"3px 8px",cursor:"pointer",fontFamily:F,fontWeight:600,marginLeft:"auto"}}>↓ Excel</button>
      </div>}
      <div style={{flex:1,overflowY:"auto"}}>
        {view==="dashboard"&&<Dashboard clients={clients} setClients={setClients} setView={setView} openClient={openClient} user={authUser} proveedores={proveedores} setProveedores={setProveedores} period={globalPeriod} setPeriod={setGlobalPeriod} config={config}/>}
        {view==="clients"&&<ClientList clients={clients} openClient={openClient} onNew={addClient} period={globalPeriod} config={config}/>}
        {view==="client"&&client&&<ClientDetail client={client} clients={clients} setClients={setClients} goBack={goBack} user={authUser} period={globalPeriod} setPeriod={setGlobalPeriod} config={config} setConfig={setConfig}/>}
        {view==="tareas"&&<TasksModule clients={clients} setClients={setClients} period={globalPeriod} user={authUser}/>}
        {view==="alertas"&&<AlertsCenter clients={clients}/>}
        {view==="calendario"&&<CalendarioView clients={clients} config={config} openClient={openClient} globalPeriod={globalPeriod}/>}
        {view==="config"&&<ConfigPanel config={config} setConfig={setConfig} tema={tema} setTema={setTema}/>}
      </div>
    </div>
  </div>
  </RCtx.Provider>;
}